        width: 140px; /* Adjusted inner circle size */
        height: 140px;
    }

    .in-circle-text {
        font-size: 16px; /* Slightly smaller text for mobile readability */
    }

    .text-block-right {
        max-width: 100%; /* Use full width on mobile */
        text-align: center; /* Center text for mobile */
        padding: 10px;
        font-size: 16px; /* Smaller text for mobile */
    }
}




/*------------------------------------------------*\
    Improve Elementor Animations
\*------------------------------------------------*/

/*------ Fades: Directional ------*/

/* FadeInDown */
@keyframes kgFadeInDown {
    from {
        opacity: 0;
        transform: translate3d(0, -12px, 0); /* Less movement than default */
    }
    to {
        opacity: 1;
        transform: none;
    }
}

.elementor-element .animated.fadeInDown {
    animation-name: kgFadeInDown !important; /* Ensure this takes precedence */
}

/* FadeInLeft */
@keyframes kgFadeInLeft {
    from {
        opacity: 0;
        transform: translate3d(-12px, 0, 0);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

.elementor-element .animated.fadeInLeft {
    animation-name: kgFadeInLeft !important;
}

/* FadeInRight */
@keyframes kgFadeInRight {
    from {
        opacity: 0;
        transform: translate3d(12px, 0, 0);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

.elementor-element .animated.fadeInRight {
    animation-name: kgFadeInRight !important;
}

/* FadeInUp */
@keyframes kgFadeInUp {
    from {
        opacity: 0;
        transform: translate3d(0, 12px, 0);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

.elementor-element .animated.fadeInUp {
    animation-name: kgFadeInUp !important;
}

/* zoomInLeft animation keyframes */
@keyframes kgZoomInLeft {
    from {
        transform: scale(1.2) translateX(-30%);
        opacity: 0;
    }
}
.elementor-element .animated.zoomInLeft {
    animation-name: kgZoomInLeft !important;
}

/* zoomInRight animation keyframes */
@keyframes kgZoomInRight {
    from {
        transform: scale(1.2) translateX(30%);
        opacity: 0;
    }
}
.elementor-element .animated.zoomInRight {
    animation-name: kgZoomInRight !important;
}

/*bounceInRight animation override*/
@keyframes kgbounceInRight {
  0% {
    opacity: 0;
    transform: translateX(200px);
  }
  60% {
    opacity: 1;
    transform: translateX(-30px);
  }
  80% { transform: translateX(10px); }
  100% { transform: translateX(0); }
}
.elementor-element .animated.bounceInRight {
    animation-name: kgbounceInRight !important;
}


/*bounceInLeft animation override*/
@keyframes kgbounceInLeft {
  0% {
    opacity: 0;
    transform: translateX(-200px);
  }
  60% {
    opacity: 1;
    transform: translateX(-30px);
  }
  80% { transform: translateX(10px); }
  100% { transform: translateX(0); }
}
.elementor-element .animated.bounceInLeft {
    animation-name: kgbounceInLeft !important;
}

/*bounceInDown animation override*/
@keyframes kgbounceInDown {
  0% {
    opacity: 0;
    transform: translateY(-200px);
  }
  60% {
    opacity: 1;
    transform: translateY(-30px);
  }
  80% { transform: translateY(10px); }
  100% { transform: translateY(0); }
}
.elementor-element .animated.bounceInDown {
    animation-name: kgbounceInDown !important;
}

/*bounceInUp animation override*/
@keyframes kgbounceInUp {
  0% {
    opacity: 0;
    transform: translateY(200px);
  }
  60% {
    opacity: 1;
    transform: translateY(30px);
  }
  80% { transform: translateY(-10px); }
  100% { transform: translateY(0); }
}
.elementor-element .animated.bounceInUp {
    animation-name: kgbounceInUp !important;
}


