/* v2.1 static compatibility overrides */
html { scroll-behavior: auto; }
body { margin: 0; }
.elementor-invisible, .animated, [data-settings*="animation"] { visibility: visible !important; opacity: 1 !important; transform: none !important; }
img { max-width: 100%; height: auto; }
a { cursor: pointer; }
.static-form-note { font-size: 0.9rem; color: #666; border-left: 3px solid #0aa; padding-left: .75rem; }


/* v2.2 static cleanup: no Elementor/WordPress runtime, no remote CSS calls */
.elementor-invisible, .animated, .elementor-widget, .elementor-section, .elementor-column, .elementor-container {
  visibility: visible !important;
  opacity: 1 !important;
}
img { max-width: 100%; height: auto; }
body { font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif; }


/* v2.3 form/static-runtime fixes */
.static-form-replacement {
  box-sizing: border-box;
  max-width: 760px;
  margin: 24px auto;
  padding: 24px;
  border: 1px solid rgba(0, 48, 64, 0.16);
  border-radius: 12px;
  background: #f7fbfc;
  color: #062b35;
  font-family: Arial, Helvetica, sans-serif;
  line-height: 1.45;
}
.static-form-replacement h2,
.static-form-replacement h3 { margin: 0 0 10px; color: #062b35; }
.static-form-replacement p { margin: 0 0 14px; }
.static-button {
  display: inline-block;
  padding: 10px 16px;
  border-radius: 999px;
  background: #00313c;
  color: #fff !important;
  text-decoration: none !important;
  font-weight: 700;
}
.static-site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 20px 8vw;
  background: #002d38;
  color: #fff;
  font-family: Arial, Helvetica, sans-serif;
}
.static-site-header a { color: #fff; text-decoration: none; }
.static-logo { font-weight: 800; }
.static-nav { display: flex; gap: 18px; flex-wrap: wrap; }
.static-contact-main { min-height: 70vh; padding: 56px 8vw; background: #fff; }
.static-contact-card { max-width: 900px; margin: 0 auto; }
.static-contact-card h1 { font-size: clamp(32px, 5vw, 56px); margin: 0 0 16px; color: #062b35; }
.pum, .pum-overlay, .popmake-overlay, [id^="pum-"], [id^="popmake-"] { display: none !important; }
form[action="#"] { pointer-events: none; opacity: .7; }
